import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Versioning","description":"","frontmatter":{},"headers":[],"relativePath":"release/versioning.md","filePath":"release/versioning.md"}'),i={name:"release/versioning.md"};function n(s,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to &quot;Versioning&quot;">​</a></h1><h2 id="the-scheme" tabindex="-1">The scheme <a class="header-anchor" href="#the-scheme" aria-label="Permalink to &quot;The scheme&quot;">​</a></h2><p>Since the v1.0.0 public release, version identifiers are <strong>SemVer</strong>: <code>1.0.0</code>, <code>1.1.0</code>, ... Before that, the engineering phase used work-package stage names (<code>WP-14-docs_release</code>, <code>WP-13-build_system</code>, ...) - the internal equivalent of a release train per feature set.</p><p>Additionally every build carries:</p><ul><li><strong>Build number</strong> = the commit count (<code>git rev-list --count HEAD</code>) at build time - monotonically increasing, published in the update manifest&#39;s <code>build</code> field (the banner/uname carry the version).</li><li><strong>Version banner</strong> = the fixed <code>OC_RELEASE_VERSION ?= 1.0.0</code> literal in the Makefile (an explicit <code>OC_RELEASE_VERSION=</code> override still wins, which is how the E2E update test works) - baked into the kernel banner, uname, the OTA manifest and the ISO. Earlier builds derived it from <code>git describe --tags</code>; v1.0.0 froze it to a literal so the banner no longer depends on local git state.</li></ul><h2 id="what-the-numbers-mean-together" tabindex="-1">What the numbers mean together <a class="header-anchor" href="#what-the-numbers-mean-together" aria-label="Permalink to &quot;What the numbers mean together&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td><code>uname -a</code></td><td><code>Open Cube OS 1.0.0 x86_64</code></td><td>the running kernel&#39;s version</td></tr><tr><td>update.json</td><td><code>version: 1.0.0, build: 275</code></td><td>the published manifest</td></tr><tr><td>Release tag</td><td><code>v1.0.0</code></td><td>the git tag the assets were built from</td></tr><tr><td>gh-pages</td><td>the same two numbers in the download page</td><td>the website mirrors the Release</td></tr></tbody></table><p>One release = one tag = one build number = one manifest = one set of SHA256s across local / Release / gh-pages / private mirror.</p><h2 id="compatibility-promises" tabindex="-1">Compatibility promises <a class="header-anchor" href="#compatibility-promises" aria-label="Permalink to &quot;Compatibility promises&quot;">​</a></h2><ul><li>Shell commands are never removed; additions are the norm (baseline moves UP: 176 -&gt; 192 -&gt; ... -&gt; 233).</li><li>L1 numbered interfaces are never renumbered; new groups append.</li><li>The OTA package updates the kernel only; /etc volume contents carry forward.</li><li>SemVer from here on: breaking changes bump MAJOR, new commands or L1 groups bump MINOR, fixes bump PATCH.</li></ul><h2 id="choosing-the-next-version" tabindex="-1">Choosing the next version <a class="header-anchor" href="#choosing-the-next-version" aria-label="Permalink to &quot;Choosing the next version&quot;">​</a></h2><p>SemVer rules above; <code>build</code> = whatever the commit count is on release day - never hand-picked.</p>',12)])])}const b=t(i,[["render",n]]);export{u as __pageData,b as default};
